begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Drive Schultz Pass Rd to Elden Lookout Rd; dirt starts at a gate about 1.9 mi in, and a pullout on the right at about 2.3 mi holds roughly five cars. If the gate is locked, park and walk the road about five minutes to the pullout.' where id='az_oaklands' and id not in (select id from _had_note);
update public.areas set parking_note='Drive Schultz Pass Rd to Elden Lookout Rd; dirt starts at a gate about 1.9 mi in, and a pullout on the right at about 2.3 mi holds roughly five cars. If the gate is locked, park and walk the road about five minutes to the pullout.' where path <@ (select path from public.areas where id='az_oaklands') and id <> 'az_oaklands' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the cul-de-sac at the end of Paradise (off Linda Vista, a block or two north of the Safeway at Cedar Ave); do not park in front of the gated chain-link fence, out of courtesy to residents.' where id='az_solitude_wall' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the cul-de-sac at the end of Paradise (off Linda Vista, a block or two north of the Safeway at Cedar Ave); do not park in front of the gated chain-link fence, out of courtesy to residents.' where path <@ (select path from public.areas where id='az_solitude_wall') and id <> 'az_solitude_wall' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Sheepshead parking area is the first one, about 0.4 mi from the Forest Road 687 junction; free primitive camping there. The approach road is rough dirt, so drive carefully in a passenger car.' where id='az_sheepshead_the' and id not in (select id from _had_note);
update public.areas set parking_note='Sheepshead parking area is the first one, about 0.4 mi from the Forest Road 687 junction; free primitive camping there. The approach road is rough dirt, so drive carefully in a passenger car.' where path <@ (select path from public.areas where id='az_sheepshead_the') and id <> 'az_sheepshead_the' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park about 2.0 mi along Forest Road 687 from the Middlemarch Rd junction at the Sweet Rock / Isle of Ewe pullout area; free primitive camping. The road is rough dirt.' where id='az_sweet_rock' and id not in (select id from _had_note);
update public.areas set parking_note='Park about 2.0 mi along Forest Road 687 from the Middlemarch Rd junction at the Sweet Rock / Isle of Ewe pullout area; free primitive camping. The road is rough dirt.' where path <@ (select path from public.areas where id='az_sweet_rock') and id <> 'az_sweet_rock' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the signed Warpath Dome approach parking about 6.5 mi up the rough Forest Road 687 from the junction; high clearance helps and road damage to cars is possible.' where id='az_warpath_dome' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the signed Warpath Dome approach parking about 6.5 mi up the rough Forest Road 687 from the junction; high clearance helps and road damage to cars is possible.' where path <@ (select path from public.areas where id='az_warpath_dome') and id <> 'az_warpath_dome' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive to the end of the road (about 10 mi past the Forest Road 687 junction) and park at the circular lot, which serves Westworld and Whale Domes; free primitive camping. The road is rough, so drive carefully.' where id='az_westworld_dome' and id not in (select id from _had_note);
update public.areas set parking_note='Drive to the end of the road (about 10 mi past the Forest Road 687 junction) and park at the circular lot, which serves Westworld and Whale Domes; free primitive camping. The road is rough, so drive carefully.' where path <@ (select path from public.areas where id='az_westworld_dome') and id <> 'az_westworld_dome' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive to the end of the road (about 10 mi past the Forest Road 687 junction) and park at the circular lot, which serves Whale and Westworld Domes; free primitive camping. The road is rough, so drive carefully.' where id='az_whale_dome' and id not in (select id from _had_note);
update public.areas set parking_note='Drive to the end of the road (about 10 mi past the Forest Road 687 junction) and park at the circular lot, which serves Whale and Westworld Domes; free primitive camping. The road is rough, so drive carefully.' where path <@ (select path from public.areas where id='az_whale_dome') and id <> 'az_whale_dome' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park in the large paved lot at Key''s Corner (Wonderland trailhead area). Hike north on a well-defined trail; this is a long approach of about an hour.' where id='ca_siberia' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the large paved lot at Key''s Corner (Wonderland trailhead area). Hike north on a well-defined trail; this is a long approach of about an hour.' where path <@ (select path from public.areas where id='ca_siberia') and id <> 'ca_siberia' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
